from pathlib import Path
import json,html,shutil
R=Path(__file__).resolve().parent
H=html.escape

def build(out):
 prompts=json.loads((R/'prompts/prompts.json').read_text())
 for folder in ['hub','fonts','prompts','screenshots']:
  shutil.copytree(R/folder,out/folder,dirs_exist_ok=True)
 def editor(key):
  p=prompts[key]
  return f'<div class="editor" id="prompt-{key}"><div class="editor-bar"><span>{H(p["folder"])} / 요청 예시</span><button class="copy" data-copy="{H(p["text"],quote=True)}">전체 복사</button></div><pre>{H(p["text"])}</pre></div>'
 def shell(title,body,kind='home'):
  return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#245b43"><title>{title} · 요즘 바이브코딩</title><link rel="stylesheet" href="hub/hub.css"></head><body data-page="{kind}"><a class="skip" href="#main">본문으로</a><header><div class="nav"><a class="brand" href="index.html"><b>v.</b>요즘 바이브코딩</a><nav aria-label="주 메뉴"><a href="index.html#examples">사례 보기</a><a href="tools.html">도구·따라하기</a><a href="reader.html">전자책</a><a href="index.html#downloads">자료 받기</a></nav></div></header><main id="main">{body}</main><footer><span>수도여자고등학교 1·2학년 · 김형훈</span><span>아는 만큼 말할 수 있고, 말하는 만큼 만들 수 있습니다.</span></footer><div class="toast" role="status" hidden></div><dialog id="copy-dialog"><h2>직접 복사하기</h2><p>선택한 글을 복사하세요.</p><textarea readonly aria-label="복사할 요청문"></textarea><form method="dialog"><button>닫기</button></form></dialog><script type="module" src="hub/hub.mjs"></script></body></html>'''
 def intro(n,title,desc):return f'<div class="intro"><span class="eyebrow">CASE {n} / 직접 보고 확인하기</span><h1>{title}</h1><p>{desc}</p></div>'
 def end(key,checks):return '<section class="outside-shot prompt-link"><h2>이 결과를 만들려면 어떻게 설명할까?</h2><p>아래는 개발창 형태로 정리한 요청 예시예요. 전체 문장을 복사해 조건과 자료를 바꿔 보세요.</p>'+editor(key)+f'<div class="panel"><h3>사람이 확인할 것</h3><ul class="checklist">{checks}</ul><a href="tools.html">도구를 열고 실행하는 순서 →</a></div></section>'
 home='''<section class="hero"><div><span class="eyebrow">수도여고 · 강의와 일상을 잇는 작업실</span><h1>내가 원하는 일,<br>직접 해 보는 쪽으로.</h1><p>학과를 비교하고, 성적을 읽고, 파일을 정리해요.<br>목표를 정하고 결과를 확인하는 건 우리 몫입니다.</p><div class="actions"><a class="btn primary" href="#examples">예제 열어 보기 ↗</a><a class="btn" href="reader.html">전자책 읽기</a></div></div><img src="assets/cover.webp" alt="강의에 등장하는 학생과 로봇 캐릭터"></section><div class="strip"><span><b>01</b>관점에서 질문으로</span><span><b>02</b>조건을 정하고 시도하기</span><span><b>03</b>확인하며 다시 배우기</span></div><section id="examples"><div class="section-head"><h2>설명으로 끝내지 말고,<br>결과를 열어 보세요.</h2><p>강사가 준비한 실행 예제입니다. 가상 점수와 연습 자료로 입력을 바꿔 보세요. 계정 없이 이용할 수 있어요.</p></div><div class="cards">'''
 for n,slug,title,desc in [('01','major','나와 맞는 학과 탐색','수업 내용과 내 관심을 나란히 놓고, 더 알아볼 질문을 남겨요.'),('02','scores','내 성적의 변화 읽기','점수만 보는 데서 한 걸음 더. 빈칸과 0점도 직접 비교해요.'),('03','files','탐구 파일 이름 정리','최종, 진짜최종, 진짜진짜최종… 이름부터 구조해 볼까요?')]:
  img=f'<img src="screenshots/{slug}.png" alt="{title} 실제 실행 화면">' if (R/f'screenshots/{slug}.png').exists() else ''
  home+=f'<article class="card"><span class="number">{n}</span><h3>{title}</h3>{img}<p>{desc}</p><div class="actions"><a class="btn" href="{slug}.html">직접 열기 →</a></div></article>'
 home+='''</div><div class="panel"><span class="badge">선택 확장</span><h3>내 활동을 내 말로 설명하기</h3><p>가상 활동과 다섯 질문, 60초 타이머로 연습해요. 없던 성과를 추가하는 기능은 없습니다.</p><a class="btn" href="interview.html">면접 연습장 열기 →</a></div></section><section id="downloads"><div class="section-head"><h2>수업 뒤에도 이어서</h2><p>프롬프트와 연습 자료를 한곳에 모았어요.</p></div><div class="step-grid"><article class="panel"><h3>도구부터 차근차근</h3><p>Codex로 폴더를 열고, 요청을 입력하고, 결과 파일을 확인하는 순서.</p><a class="btn primary" href="tools.html">도구·따라하기</a><a class="btn" href="prompts.html">프롬프트 모음</a></article><article class="panel"><h3>내려받아 보관하기</h3><div class="actions"><a class="btn" href="guidebook.pdf" download>전자책 PDF</a><a class="btn" href="downloads/practice-kit.zip" download>연습 자료 ZIP</a><a class="btn" href="downloads/recommended-book.pdf" download>추천도서 안내</a><a class="btn" href="downloads/slides.pdf" download>강의 슬라이드 PDF</a></div></article></div></section><section class="study-note"><h2>그래서 결론은… 공부하세요.</h2><p>관점을 바꾸면 질문이 생기고, 아는 것이 늘면 더 구체적으로 설명하고 판단할 수 있어요. 다음 스테이지는 내일 1교시입니다.</p></section>'''
 (out/'index.html').write_text(shell('강의 허브',home).replace('<script type="module"','<script>if(/^#p=/.test(location.hash))location.replace("reader.html"+location.hash)</script><script type="module"'))
 scores=intro('02','점수 뒤의 질문을 찾아요.','가상 원점수로 만든 그래프입니다. 데이터를 바꾸고, 표시된 값이 맞는지 직접 확인해 보세요.')+'''<div class="workspace"><section class="panel"><h2>① 자료 입력</h2><label for="scores-csv">가상 CSV · 100점 만점</label><textarea id="scores-csv" spellcheck="false" rows="6">과목,시험1,시험2,시험3
수학,72,78,81
영어,86,82,84</textarea><div class="actions"><button class="primary" id="draw-scores">그래프 다시 그리기</button></div><div class="toolbar"><button data-sample="normal">기본 자료</button><button data-sample="gap">빈칸</button><button data-sample="zero">0점</button><button data-sample="invalid">101점</button></div><p class="muted">빈칸은 자료 없음, 0은 실제 점수예요. 입력은 이 페이지에서만 처리해요.</p><label for="labels">점수 표시</label><select id="labels"><option value="on">점 옆에 숫자 표시</option><option value="off">선과 점만 표시</option></select><p id="scores-error" class="error" role="alert" hidden></p><a href="examples/scores.csv" download>예제 CSV 받기</a></section><div class="result"><section class="panel" id="score-result" aria-live="polite"><span class="badge">② 결과와 원자료 대조</span><div class="metrics" id="metrics"></div><div id="chart"></div><div class="table-scroll" id="score-table"></div><p class="muted">시험마다 난도와 출제 범위가 달라요. 점수 변화만으로 실력이나 합격 가능성을 판단할 수는 없어요.</p></section><div class="toolbar"><button id="download-report">현재 보고서 HTML 받기</button><button id="download-scores">현재 자료 CSV 받기</button></div></div></div><section class="panel outside-shot"><h2>③ 다음 공부는 내가 정하기</h2><label for="study-plan">오답에서 반복된 실수와 다음 공부 한 가지</label><textarea id="study-plan" placeholder="예: 조건을 놓친 문제가 3개였다. 다음에는 문제의 조건에 밑줄을 긋고 풀어 보자."></textarea><button id="download-plan">내 계획 TXT 받기</button><p class="muted">메모는 새로고침하면 지워져요. 필요하면 파일로 받아 두세요.</p></section>'''+end('scores','<li>수학 +9점, 영어 −2점이 원자료 계산과 같은가요?</li><li>빈칸에서 선이 끊기고 0점은 축 위에 표시되나요?</li><li>101점을 넣었을 때 이전 그래프를 새 결과로 오해하지 않게 오류가 보이나요?</li>')
 (out/'scores.html').write_text(shell('성적 분석',scores,'scores'))
 major=intro('01','학과 이름 다음을 읽어요.','공식 교육과정에 있는 내용과 내 해석을 나란히 적어 보세요. 세 학과는 비교 방법을 보여 주는 사례이며 추천 순위가 아니에요.')+'''<section class="panel" id="major-result"><span class="badge">공식 자료 + 내가 적는 연결점</span><p class="muted">자료 확인: 2026-10-19 · 아래 입력란의 첫 문장은 가상 학생의 예시예요. 지원 조건은 해당 연도 공식 모집요강과 별도로 확인하세요.</p><div id="major-rows"></div><div class="actions"><button class="primary" id="download-majors">선택한 학과 비교표 CSV 받기</button><button id="add-major">내 후보 학과 추가</button></div><p id="major-status" role="status"></p></section>'''+end('major','<li>과목명과 출처가 실제 교육과정과 일치하나요?</li><li>내 관심과의 연결은 사실과 구별한 나의 해석인가요?</li><li>수업 내용을 더 알아보기 위한 질문이 남았나요?</li>')
 (out/'major.html').write_text(shell('학과 탐색',major,'major'))
 files=intro('03','진짜최종 파일을 구출하자.','확인한 대응표로 파일 이름을 정리해요. 이 화면은 미리보기이며 컴퓨터의 파일 이름을 바꾸지 않습니다.')+'''<section class="panel" id="file-result"><span class="badge">먼저 확인하고, 그다음 적용하기</span><div class="table-scroll"><table><thead><tr><th>기존 이름</th><th>새 이름 · 직접 수정 가능</th><th>검사</th></tr></thead><tbody id="file-rows"></tbody></table></div><div class="actions"><button id="rename-check" class="primary">대응표 검사</button><button id="duplicate-demo">이름 중복 예시</button><button id="reset-files">기본 대응표</button></div><p id="rename-status" role="status"></p><div class="actions"><button id="download-mapping">확인한 대응표 CSV 받기</button><a class="btn" href="downloads/file-practice.zip" download>연습 파일 + 실행 코드 ZIP</a></div><p class="muted">실제 파일 존재 여부와 폴더 안의 다른 파일은 내려받은 코드에서 다시 확인해요.</p></section><section class="panel outside-shot"><h2>내 컴퓨터에서 적용하는 순서</h2><ol class="steps"><li><b>연습 파일 ZIP을 풀어요.</b>원본 자료와 분리된 폴더에서 시작해요.</li><li><b>미리보기 결과를 확인해요.</b><code class="code">python rename_files.py</code></li><li><b>확인한 복사본에만 적용해요.</b><code class="code">python rename_files.py --apply</code></li><li><b>파일 수와 내용을 확인해요.</b>변경 기록은 rename-log.csv로 남아요.</li></ol><p>Windows에서는 Python 설치 상태에 따라 <code>python</code> 대신 <code>py</code>, macOS에서는 <code>python3</code>를 사용해요.</p></section>'''+end('files','<li>날짜와 과목을 추측해서 넣지 않았나요?</li><li>확장자가 같고 새 이름이 서로 겹치지 않나요?</li><li>실제 적용은 연습 폴더에서만 했나요?</li>')
 (out/'files.html').write_text(shell('파일 이름 정리',files,'files'))
 interview=intro('+','내가 한 일을, 내 말로.','수업용 가상 활동을 보며 설명을 연습해요. 질문을 고르고 60초 동안 말해 보세요.')+'''<div class="step-grid"><section class="panel"><h2>활동 기록</h2><p id="activity">일회용 컵을 줄이는 방안을 탐구하며 설문 질문을 만들고 응답을 정리했다. 컵을 씻는 곳과 들고 다니는 불편을 개선하자고 제안했다. 응답자 범위에 한계가 있어 전교생의 생각이라고 단정할 수 없다.</p><label for="question">연습 질문</label><select id="question"><option>어떤 역할을 맡았나요?</option><option>설문 질문을 만들 때 무엇을 고민했나요?</option><option>응답에서 어떤 불편을 살펴봤나요?</option><option>결과를 해석할 때 어떤 한계가 있었나요?</option><option>다시 한다면 무엇을 바꾸고 싶나요?</option></select><p id="active-question"></p><label for="interview-note">내 답변 메모</label><textarea id="interview-note"></textarea><p class="muted">메모는 저장·전송하지 않으며 새로고침하면 사라져요.</p></section><section class="panel"><span class="badge">연습용 시간 · 대학 공통 규칙 아님</span><div class="timer" role="timer" id="timer">01:00</div><div class="actions"><button id="timer-start" class="primary">시작</button><button id="timer-stop">정지</button><button id="timer-reset">초기화</button></div><p id="timer-status" role="status"></p><details open><summary>복사할 연습 요청문</summary><pre id="interview-prompt" style="white-space:pre-wrap;font:inherit"></pre></details><button id="copy-interview">이 질문으로 요청문 복사</button></section></div>'''+end('interview','<li>기록에 없던 성과·수치·역할을 덧붙이지 않았나요?</li><li>설문 결과의 한계를 설명했나요?</li><li>타이머와 복사 버튼이 선택한 질문에 맞게 작동하나요?</li>')
 (out/'interview.html').write_text(shell('활동 설명 연습',interview,'interview'))
 pbody='<span class="eyebrow">COPY → TRY → CHECK</span><h1>조건은 구체적으로.<br>복사는 한 번에.</h1><p>아래 개발창은 요청문을 읽기 쉽게 재구성한 예시예요. 실제 서비스의 실행 기록은 아닙니다. 목표와 자료를 확인하고 복사하세요.</p>'
 for k,p in prompts.items():pbody+=f'<section><h2>{p["title"]}</h2>'+editor(k)+'</section>'
 (out/'prompts.html').write_text(shell('프롬프트 모음',pbody,'prompts'))
 for k,p in prompts.items():(out/f'prompt-{k}.html').write_text(shell(p['title'],'<div class="shot-frame"><span class="eyebrow">개발창 형태로 재구성한 요청 예시</span><h1>'+p['title']+'</h1>'+editor(k)+'</div>','prompt'))
 tools='''<span class="eyebrow">처음 시작하는 사람을 위한 안내</span><h1>어떤 도구를,<br>어느 순서로 쓸까요?</h1><p class="intro">예제는 브라우저에서 바로 볼 수 있어요. 직접 만들 때는 Codex와 작업 폴더, 결과를 열 브라우저를 사용합니다. 수업에서는 선생님의 시연을 보고, 혼자 따라하기는 수업 뒤에 선택하세요.</p><div class="step-grid"><section class="panel"><h2>먼저 열어 보기</h2><p>휴대폰이나 PC 브라우저로 허브 예제를 이용해요. 설치·로그인 없이 값과 조건을 바꿔 볼 수 있습니다.</p><a class="btn" href="scores.html">성적 예제로 시작</a></section><section class="panel"><h2>직접 만들어 보기</h2><p>PC에서 Codex로 연습 폴더를 열고 파일을 만들거나 수정해요. 설치와 로그인은 공식 안내를 따라 준비하세요.</p><a href="https://learn.chatgpt.com/docs/cli" target="_blank" rel="noopener">Codex CLI 공식 안내 ↗</a><br><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noopener">데스크톱 앱 공식 안내 ↗</a></section></div><section class="panel"><h2>주 경로 · 폴더에서 Codex 시작하기</h2><ol class="steps"><li><b>연습 자료를 내려받고 압축을 풀어요.</b><a href="downloads/practice-kit.zip" download>practice-kit.zip</a> 안의 study-check 폴더에는 scores.csv가 있어요.</li><li><b>Codex를 설치하고 로그인해요.</b>공식 안내에서 운영체제에 맞는 설치 방법을 확인하세요. 사용 가능 여부와 계정 조건도 확인해요.</li><li><b>터미널에서 폴더를 열어요.</b>터미널은 명령을 입력하는 창이에요. Windows에서는 폴더에서 ‘터미널에서 열기’를 사용할 수 있어요. macOS에서는 터미널에 cd와 공백을 입력한 뒤 폴더를 끌어 놓고 Enter를 누르세요.</li><li><b>codex를 입력해 시작해요.</b>표시된 작업 폴더가 study-check인지 확인하고, 아래 요청문을 붙여 넣어요.</li><li><b>파일 변경과 실행 내용을 확인해요.</b>작업 폴더와 실행할 내용을 읽고 진행하세요. 전체 컴퓨터 접근이나 불필요한 삭제를 허용할 필요는 없어요.</li><li><b>결과 파일을 브라우저로 열어요.</b>report.html을 열고 원자료와 숫자를 대조해요. 코드가 화면에 나타난 것과 실제 실행은 구분해야 해요.</li></ol><p class="source">안내 확인: 2026-10-19. 로컬 Codex CLI 0.163.0의 도움말과 <a href="https://learn.chatgpt.com/docs/cli">공식 시작 안내</a>를 기준으로 작성했습니다. 서비스 화면과 메뉴 이름은 버전에 따라 달라질 수 있어요.</p></section><section class="panel"><h2>앱 화면을 이용한다면</h2><p>데스크톱 앱에서 폴더를 열고 새 대화를 시작한 뒤 같은 요청문을 입력할 수 있어요. 작업 폴더에 가상 자료가 들어 있는지 먼저 확인하세요. <a href="https://learn.chatgpt.com/docs/app">공식 앱 안내</a>에서 현재 화면을 확인할 수 있습니다.</p><p>웹 채팅만 쓴다면 생성된 HTML을 파일로 내려받는 방법을 확인하세요. 파일 이름이 report.html.txt가 되지 않았는지도 살펴보세요. 터미널 작업과 같은 방식으로 실행됐다고 가정하지 마세요.</p></section>'''+editor('scores')+'''<section class="panel"><h2>오류가 나면 이 순서로</h2><p>작업 폴더 → 파일명과 확장자 → 원자료 → 오류 문구 → 실행 방법을 확인해요. “안 돼요”만으로는 어디서 막혔는지 알기 어려워요. 시험지에 이름만 쓰고 제출한 느낌이랄까요.</p><a class="btn" href="prompts.html#prompt-debug">오류 설명 요청문 보기</a></section>'''
 (out/'tools.html').write_text(shell('도구와 따라하기',tools,'tools'))
if __name__=='__main__':build(R/'dist')
